import React, { useState } from "react";
import {
  Users, UserPlus, LogOut, Shield, Copy, Check,
  Search, Crown, Mail, MoreVertical
} from "lucide-react";
import { useWorkspace } from "../context/WorkspaceContext";
import { useAuth } from "../context/AuthContext";
import { Avatar } from "../components/layout/Sidebar";
import api from "../utils/api";

const ROLE_CONFIG = {
  owner:  { classes: "bg-amber-500/15 text-amber-300 border-amber-500/20",   icon: Crown,  glow: "0 0 12px rgba(245,158,11,0.20)" },
  admin:  { classes: "bg-violet-500/15 text-violet-300 border-violet-500/20", icon: Shield, glow: "0 0 12px rgba(124,58,237,0.20)" },
  member: { classes: "bg-slate-700/40 text-slate-400 border-slate-700/60",    icon: null,   glow: null },
  viewer: { classes: "bg-slate-800/60 text-slate-500 border-slate-700/40",    icon: null,   glow: null },
};

const RoleBadge = ({ role }) => {
  const cfg = ROLE_CONFIG[role] || ROLE_CONFIG.member;
  const Icon = cfg.icon;
  return (
    <span
      className={`px-2.5 py-1 rounded-full text-xs font-semibold border flex items-center gap-1.5
        ${cfg.classes}`}
      style={cfg.glow ? { boxShadow: cfg.glow } : undefined}
    >
      {Icon && <Icon size={10} />}
      {role.charAt(0).toUpperCase() + role.slice(1)}
    </span>
  );
};

// ─── Invite Section ───────────────────────────────────────────────────────────
const InviteSection = ({ workspaceId, canInvite }) => {
  const { inviteMember } = useWorkspace();
  const [email, setEmail]   = useState("");
  const [role, setRole]     = useState("member");
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState(null);
  const [copied, setCopied] = useState(false);

  if (!canInvite) return null;

  const handleInvite = async (e) => {
    e.preventDefault();
    if (!email.trim()) return;
    setLoading(true);
    setResult(null);
    const res = await inviteMember(workspaceId, email.trim(), role);
    setLoading(false);
    setResult(res);
    if (res.success) setEmail("");
  };

  const copyLink = () => {
    if (result?.invite?.inviteLink) {
      navigator.clipboard.writeText(result.invite.inviteLink);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    }
  };

  return (
    <div className="glass rounded-2xl overflow-hidden animate-fade-in">
      <div className="px-6 py-4 border-b border-white/5 flex items-center gap-3">
        <div className="w-8 h-8 rounded-lg bg-violet-500/15 flex items-center justify-center">
          <UserPlus size={15} className="text-violet-400" />
        </div>
        <h3 className="text-base font-bold text-white">Invite members</h3>
      </div>
      <div className="p-6">
        <form onSubmit={handleInvite} className="space-y-3">
          <div className="flex gap-3">
            <div className="flex-1 relative">
              <Mail size={14} className="absolute left-3.5 top-1/2 -translate-y-1/2 text-slate-500" />
              <input
                id="invite-email"
                type="email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                placeholder="colleague@company.com"
                className="input-field pl-9"
              />
            </div>
            <select
              value={role}
              onChange={(e) => setRole(e.target.value)}
              className="input-field select w-32 flex-shrink-0"
            >
              <option value="member">Member</option>
              <option value="admin">Admin</option>
              <option value="viewer">Viewer</option>
            </select>
          </div>
          <button
            type="submit"
            disabled={loading || !email.trim()}
            className="btn-primary"
          >
            <UserPlus size={14} />
            {loading ? "Sending…" : "Send invite"}
          </button>
        </form>

        {result && (
          <div
            className={`mt-4 p-4 rounded-xl border text-sm animate-fade-in
              ${result.success
                ? "bg-emerald-500/8 border-emerald-500/20 text-emerald-400"
                : "bg-red-500/8 border-red-500/20 text-red-400"
              }`}
          >
            {result.success ? (
              <div className="space-y-3">
                <div className="flex items-center gap-2">
                  <span className="w-4 h-4 rounded-full bg-emerald-500/20 flex items-center justify-center flex-shrink-0">
                    <Check size={10} className="text-emerald-400" />
                  </span>
                  <span className="font-semibold">Invite link created!</span>
                </div>
                <div className="flex items-center gap-2 bg-slate-800/60 px-3 py-2 rounded-xl
                  border border-slate-700/40">
                  <code className="flex-1 text-xs text-slate-300 truncate">
                    {result.invite?.inviteLink}
                  </code>
                  <button
                    onClick={copyLink}
                    className={`p-1.5 rounded-lg transition-all flex-shrink-0
                      ${copied ? "text-emerald-400 bg-emerald-500/15" : "text-slate-400 hover:text-white hover:bg-slate-700"}`}
                    title="Copy link"
                  >
                    {copied ? <Check size={13} /> : <Copy size={13} />}
                  </button>
                </div>
              </div>
            ) : (
              <div className="flex items-center gap-2">
                <span className="w-1.5 h-1.5 rounded-full bg-red-400 flex-shrink-0" />
                {result.message}
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

// ─── Member Row ───────────────────────────────────────────────────────────────
const MemberRow = ({ member, currentUserId, userRole, workspaceId, onRemove }) => {
  const isSelf = member.user?._id === currentUserId;
  const canRemove =
    isSelf || (["owner", "admin"].includes(userRole) && member.role !== "owner");
  const [removing, setRemoving] = useState(false);

  const handleRemove = async () => {
    if (!window.confirm(isSelf ? "Leave this workspace?" : `Remove ${member.user?.name}?`)) return;
    setRemoving(true);
    try {
      await api.delete(`/workspaces/${workspaceId}/members/${member.user?._id}`);
      onRemove(member.user?._id);
    } catch (err) {
      console.error(err);
    } finally {
      setRemoving(false);
    }
  };

  return (
    <div className="flex items-center gap-4 py-3.5 px-2 rounded-xl group
      hover:bg-white/3 transition-all animate-fade-in">
      <div className="relative flex-shrink-0">
        <Avatar user={member.user} size="md" online={isSelf} />
      </div>
      <div className="flex-1 min-w-0">
        <p className="text-sm font-semibold text-white truncate">
          {member.user?.name || "Unknown"}
          {isSelf && <span className="ml-2 text-xs text-slate-500 font-normal">(you)</span>}
        </p>
        <p className="text-xs text-slate-500 truncate">{member.user?.email}</p>
      </div>
      <div className="flex items-center gap-3 flex-shrink-0">
        <RoleBadge role={member.role} />
        {canRemove && (
          <button
            onClick={handleRemove}
            disabled={removing}
            title={isSelf ? "Leave workspace" : "Remove member"}
            className="opacity-0 group-hover:opacity-100 p-1.5 rounded-xl text-slate-600
              hover:text-red-400 hover:bg-red-500/10 transition-all disabled:opacity-30"
          >
            <LogOut size={14} />
          </button>
        )}
      </div>
    </div>
  );
};

// ─── Members Page ─────────────────────────────────────────────────────────────
const MembersPage = () => {
  const { activeWorkspace, setWorkspaces } = useWorkspace();
  const { user } = useAuth();
  const [search, setSearch] = useState("");

  if (!activeWorkspace) {
    return (
      <div className="flex flex-col items-center justify-center h-full text-center py-20 animate-fade-in">
        <div className="w-16 h-16 rounded-2xl glass flex items-center justify-center text-3xl mb-4">👥</div>
        <h3 className="text-lg font-bold text-white mb-2">No workspace selected</h3>
        <p className="text-slate-500 text-sm">Select a workspace from the sidebar first.</p>
      </div>
    );
  }

  const userRole = activeWorkspace.members?.find((m) => m.user?._id === user?._id)?.role || "member";
  const canInvite = ["owner", "admin"].includes(userRole);
  const members = activeWorkspace.members || [];
  const filtered = search.trim()
    ? members.filter((m) =>
        m.user?.name?.toLowerCase().includes(search.toLowerCase()) ||
        m.user?.email?.toLowerCase().includes(search.toLowerCase())
      )
    : members;

  const handleRemove = (userId) => {
    setWorkspaces((prev) =>
      prev.map((ws) =>
        ws._id === activeWorkspace._id
          ? { ...ws, members: ws.members.filter((m) => m.user?._id !== userId) }
          : ws
      )
    );
  };

  return (
    <div className="max-w-2xl mx-auto px-6 py-8 space-y-6">
      {/* ── Page header with workspace banner ──────────────────────── */}
      <div
        className="relative rounded-2xl overflow-hidden p-6 animate-fade-in"
        style={{
          background: activeWorkspace.color
            ? `linear-gradient(135deg, ${activeWorkspace.color}30, ${activeWorkspace.color}10, transparent)`
            : "linear-gradient(135deg, rgba(124,58,237,0.20), transparent)",
          border: `1px solid ${activeWorkspace.color || "#7c3aed"}22`,
        }}
      >
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-4">
            <div
              className="w-12 h-12 rounded-xl flex items-center justify-center text-2xl flex-shrink-0
                shadow-lg"
              style={{
                background: activeWorkspace.color
                  ? `linear-gradient(135deg, ${activeWorkspace.color}, ${activeWorkspace.color}88)`
                  : "linear-gradient(135deg, #7c3aed, #4f46e5)"
              }}
            >
              {activeWorkspace.icon}
            </div>
            <div>
              <h1 className="text-xl font-black text-white">{activeWorkspace.name}</h1>
              <p className="text-sm text-slate-400 mt-0.5">
                {members.length} member{members.length !== 1 ? "s" : ""}
              </p>
            </div>
          </div>
          <div className="flex items-center gap-2 px-3 py-1.5 rounded-full glass
            border border-violet-500/20 text-xs font-semibold text-violet-300">
            <Users size={12} />
            {members.length}
          </div>
        </div>
      </div>

      {/* ── Members list ─────────────────────────────────────────────── */}
      <div className="glass rounded-2xl overflow-hidden animate-fade-in">
        <div className="px-6 py-4 border-b border-white/5">
          <div className="flex items-center gap-3">
            <div className="w-8 h-8 rounded-lg bg-violet-500/15 flex items-center justify-center">
              <Users size={15} className="text-violet-400" />
            </div>
            <h3 className="text-base font-bold text-white flex-1">Members</h3>
            {/* Search */}
            <div className="flex items-center gap-2 bg-slate-800/60 border border-slate-700/40
              rounded-xl px-3 py-1.5">
              <Search size={12} className="text-slate-500" />
              <input
                type="text"
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                placeholder="Search…"
                className="bg-transparent text-white text-xs placeholder-slate-500
                  focus:outline-none w-28"
              />
            </div>
          </div>
        </div>

        <div className="px-4 py-2">
          {filtered.length === 0 ? (
            <p className="py-8 text-center text-slate-500 text-sm">No members found.</p>
          ) : (
            <div className="divide-y divide-white/4">
              {filtered.map((member) => (
                <MemberRow
                  key={member.user?._id || member.user}
                  member={member}
                  currentUserId={user?._id}
                  userRole={userRole}
                  workspaceId={activeWorkspace._id}
                  onRemove={handleRemove}
                />
              ))}
            </div>
          )}
        </div>
      </div>

      {/* ── Invite section ─────────────────────────────────────────── */}
      <InviteSection workspaceId={activeWorkspace._id} canInvite={canInvite} />
    </div>
  );
};

export default MembersPage;
